const fold = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
let indexedItems=null,itemIndex=new Map();
const item = id => {if(indexedItems!==state.items){indexedItems=state.items;itemIndex=new Map(state.items.map(value=>[value.id,value]));}return itemIndex.get(id);};
const saved = value => value.pinned || value.retainedAt!=null || value.folderIds?.length || value.tags?.length;
const title = value => value.name || value.title || (value.kind==='text' ? value.text?.split('\n')[0] : value.kind==='link' ? value.url : value.recording ? 'Video' : 'Image') || 'Untitled';
const thumbnail = value => { const url=value?.thumbnailUrl || value?.mediaUrl || ''; return /^appmedia:\/\/media\/[a-f0-9-]+(?:\/original|\/thumbnail)?(?:\?[^\s]*)?$/.test(url) || /^data:image\/(png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(url) ? url : ''; };
const previewMedia = value => thumbnail(value?.kind==='image'?{...value,thumbnailUrl:''}:value);
const recording = value => value?.kind==='image'&&value.recording===true;
function recordingURL(value){const url=value?.videoUrl||'';return recording(value)&&url.split('?')[0]==='appmedia://media/'+value.id+'/video'?url:'';}
function mediaTime(ms){const centiseconds=Math.max(0,Math.round((Number(ms)||0)/10)),minutes=Math.floor(centiseconds/6000);return minutes+':'+((centiseconds%6000)/100).toFixed(2).padStart(5,'0');}

const hotkey = action => state.settings.localShortcuts?.[action] ?? DEFAULT_KEYS[action] ?? '';
function shortcutContext(){if(ui.editingText)return'textEditing';if(ui.editor)return'imageMarkup';if(ui.preview)return item(ui.preview)?.kind+'Preview';return ui.view;}
function shortcutAllowed(action,context=shortcutContext()){
 if(action==='actions')return true;
 if(['focusNextPane','focusPreviousPane','newNote','newFolder'].includes(action))return context==='library';
 if(action==='undoTrash')return context==='library'||ui.view==='library'&&context.endsWith('Preview');
 if(context==='settings')return action==='close';
 if(context==='textEditing')return ['finishEditing','pin','pinnedOnly'].includes(action);
 if(['copy','paste'].includes(action))return true;
 if(context==='imageMarkup')return ['markup','crop',...Object.keys(MARKUP_TOOLS)].includes(action);
 if(Object.hasOwn(MARKUP_TOOLS,action))return false;
 if(action==='finishEditing')return false;
 if(action==='switchShelf')return context==='shelves'||context.endsWith('Preview')&&ui.view==='shelves';
 if(['library','toggleShelves','toggleLinks','toggleTexts','toggleImages','search'].includes(action)||/^select[1-9]$/.test(action))return context==='shelves';
 if(['librarySearch','allTypes','images','texts','links'].includes(action))return context==='library';
 if(['extendPrevious','extendNext','extendUp','extendDown','selectAll','export'].includes(action))return context==='shelves'||context==='library';
 if(action==='trash')return context==='shelves'||context==='library'||ui.view==='library'&&context.endsWith('Preview');
 if(['first','last','previousPage','nextPage'].includes(action))return context==='shelves'||context==='library'||context.endsWith('Preview');
 if(action==='remove')return context==='shelves'||context.endsWith('Preview')&&ui.view==='shelves';
 if(action==='undo')return context==='shelves'||context.endsWith('Preview')&&ui.view==='shelves';
 if(action==='open')return context==='library'||context==='linkPreview';
 if(action==='edit')return context==='textPreview'||context==='library';
 if(['markup','crop'].includes(action))return context==='imagePreview'||context==='library';
 if(action==='copyOCR')return context==='shelves'||context==='library'||context==='imagePreview';
 return true;
}
// Physical Key*/Digit* codes remain authoritative. Synthetic/native input can
// omit them, so ASCII fallback letters and saved legacy letters share one form.
function canonicalShortcut(value){return value.replace(/(^|\+)([a-z])$/,(_match,prefix,key)=>prefix+key.toUpperCase());}
function shortcutCandidates(action,context=shortcutContext()){
 if(!shortcutAllowed(action,context))return[];
 const stored=state.settings.localShortcuts||{};
 if(Object.hasOwn(stored,action)){const key=canonicalShortcut(stored[action]||'');return key&&!(action==='undoTrash'&&context==='imagePreview'&&key==='Ctrl+Z')?[key]:[];}
 const values=[DEFAULT_KEYS[action],...(DEFAULT_ALIASES[action]||[])].filter(Boolean);
 if(action==='trash'&&(context==='library'||ui.view==='library'&&context.endsWith('Preview')))return ['S',...values,'Ctrl+Backspace'].map(canonicalShortcut);
 if(action==='undoTrash'&&(context==='library'||ui.view==='library'&&context.endsWith('Preview')))return ['Backspace',...values].map(canonicalShortcut).filter(key=>context!=='imagePreview'||key!=='Ctrl+Z');
 return values.map(canonicalShortcut);
}
function resolveShortcut(shortcut,context=shortcutContext()){
 if(!shortcut)return null;shortcut=canonicalShortcut(shortcut);const stored=state.settings.localShortcuts||{},actions=Object.keys(DEFAULT_KEYS);
 return actions.find(action=>Object.hasOwn(stored,action)&&shortcutCandidates(action,context).includes(shortcut))||actions.find(action=>shortcutCandidates(action,context).includes(shortcut))||null;
}
function effectiveShortcut(action,context=shortcutContext()){return shortcutCandidates(action,context).filter(value=>resolveShortcut(value,context)===action).join(' / ');}
function shortcutSettingLabel(action){const stored=state.settings.localShortcuts||{};if(Object.hasOwn(stored,action))return stored[action]||t('Off');const contexts=['trash','undoTrash','focusNextPane','focusPreviousPane','newNote','newFolder'].includes(action)?['library']:['shelves','library','imagePreview','textPreview','linkPreview','imageMarkup','textEditing'];return[...new Set(contexts.flatMap(context=>shortcutCandidates(action,context).filter(value=>resolveShortcut(value,context)===action)))].join(' / ');}
const keyHint = action => effectiveShortcut(action) ? `<kbd>${esc(effectiveShortcut(action).replaceAll('Arrow',''))}</kbd>` : '';
function toast(message) { const target=document.getElementById('toast'); target.textContent=message; target.classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>target.classList.remove('visible'),3500); }
function visibleKinds() { return state.settings.visibleKinds?.length ? KINDS.filter(kind=>state.settings.visibleKinds.includes(kind)) : KINDS; }
let tokenQuery=null,searchTokens=[];
function matches(value,query) { const hay=fold([value.name,value.title,value.text,value.url,value.uploadedUrl,value.note,value.ocrText,...(value.tags||[])].join(' '));if(tokenQuery!==query){tokenQuery=query;searchTokens=fold(query).trim().split(/\s+/);}return searchTokens.every(token=>hay.includes(token)); }
let shelfItemsSource=null,shelfItemsQuery=null,shelfRows=new Map();
function rowItems(kind) {
 if(shelfItemsSource!==state.items||shelfItemsQuery!==ui.search){shelfItemsSource=state.items;shelfItemsQuery=ui.search;shelfRows.clear();}
 const key=kind+':'+!!ui.pinned[kind];if(!shelfRows.has(key))shelfRows.set(key,state.items.filter(value=>value.kind===kind&&!value.trashedAt&&!value.hiddenFromShelf&&(!ui.pinned[kind]||value.pinned)&&(!ui.search||matches(value,ui.search))).sort((a,b)=>b.createdAt-a.createdAt));return shelfRows.get(key);
}
function folderIncludes(value,id) { const ids=new Set([id]); let changed=true; while(changed){changed=false; for(const folder of state.folders)if(ids.has(folder.parentId)&&!ids.has(folder.id)){ids.add(folder.id);changed=true;}} return value.folderIds?.some(folder=>ids.has(folder)); }
function libraryBaseItems() { return state.items.filter(value=>{
 if(ui.scope==='trash' ? !value.trashedAt : value.trashedAt)return false;
 if(ui.scope==='saved'&&!saved(value))return false;
 if(ui.scope==='recent'&&saved(value))return false;
 if(ui.favoritesOnly&&!value.pinned)return false;
 if(ui.scope==='pinned'&&!value.pinned)return false;
 if(ui.scope==='unorganized'&&(!saved(value)||value.folderIds?.length||value.tags?.length))return false;
 if(ui.scope==='folder'&&!folderIncludes(value,ui.folder))return false;
 if(ui.scope==='tag'&&!value.tags?.includes(ui.tag))return false;
 if(ui.type!=='all'&&value.kind!==ui.type)return false;
 if(ui.filterTags.some(tag=>!value.tags?.includes(tag)))return false;
 if(ui.days&&value.createdAt<Date.now()-ui.days*86400000)return false;
 if(ui.domain){try{const host=new URL(value.url).hostname.replace(/^www\./,'');const wanted=ui.domain.replace(/^www\./,'').toLowerCase();if(host!==wanted&&!host.endsWith('.'+wanted))return false;}catch{return false;}}
 return true;
 }); }
function libraryItems(){const values=libraryBaseItems().filter(value=>{if(!ui.search)return true;const textMatch=matches(value,ui.search),visualMatch=value.kind==='image'&&libraryImageSearch.ids.has(value.id);return ui.searchMode==='visual'?visualMatch:ui.searchMode==='text'?textMatch:textMatch||visualMatch;});return values.sort((a,b)=>ui.sort==='oldest'?a.createdAt-b.createdAt:ui.sort==='title'?title(a).localeCompare(title(b)):ui.sort==='titleDescending'?title(b).localeCompare(title(a)):ui.sort==='relevance'?libraryRelevance(b)-libraryRelevance(a)||b.createdAt-a.createdAt:ui.sort==='copied'?(b.lastCopiedAt||b.copiedAt||b.updatedAt)-(a.lastCopiedAt||a.copiedAt||a.updatedAt):b.createdAt-a.createdAt);}
