function dialog(titleText,body,footer='',className='') {return `<div class="modal-backdrop"><section class="dialog ${className}" role="dialog" aria-modal="true" aria-label="${attr(t(titleText))}"><header><h2 class="${className==='palette'?'palette-mode':''}">${className==='palette'?icon('actions'):''}${esc(t(titleText))}</h2><div class="grow"></div>${className==='palette'?`<button class="quiet palette-search-switch" data-action="search">${icon('search')}${esc(t('Search contents'))}</button>`:''}<button class="quiet" data-action="close-modal" aria-label="${attr(t('Close'))}">${icon('close')}</button></header><div class="dialog-body">${body}</div>${footer?`<footer>${footer}</footer>`:''}</section></div>`;}
let shortcutRecorderSerial=0;
